Matching Ayahs
- = Alif, Lam, Mim. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Những người đó ở trên con đường ngay thẳng từ Thượng Đế của họ, và chính họ là những người thành công. 2:5; 31:5
- = Hỡi con cháu của Israel, hãy nhớ lại Ân huệ của Ta mà Ta đã ban cho các ngươi và việc Ta đã ưu ái các ngươi hơn các dân tộc (thế giới). 2:47; 2:122
- = Đó là một cộng đồng đã qua. Họ sẽ nhận được những gì họ đã làm ra, và các ngươi sẽ nhận được những gì các ngươi đã làm ra. Và các ngươi sẽ không bị chất vấn về những điều họ đã làm. 2:134; 2:141
- = Họ sẽ ở trong đó vĩnh viễn; hình phạt sẽ không được giảm nhẹ cho họ, và họ sẽ không được trì hoãn. 2:162; 3:88
- = Ngoại trừ những ai sau đó ăn năn sám hối và sửa mình. Quả thật, Allah là Đấng Tha Thứ, Đấng Nhân Từ. 3:89; 24:5
- = Còn những ai vô đức tin và phủ nhận các dấu hiệu của Ta – họ là những người bạn của Hỏa Ngục. 5:10; 5:86
- = Và không có dấu hiệu nào từ các dấu hiệu của Thượng Đế của họ đến với họ, mà họ lại quay mặt bỏ đi. 6:4; 36:46
- = Và quả thật, các Sứ Giả đã bị nhạo báng trước ngươi, nhưng những kẻ nhạo báng đã bị bao vây bởi điều mà họ đã từng nhạo báng. 6:10; 21:41
- = Hãy nói: "Quả thật, Ta sợ, nếu Ta bất tuân Thượng Đế của Ta, hình phạt của một Ngày vĩ đại." 6:15; 39:13
- = Vậy cơn động đất đã bắt lấy họ, và họ trở thành những xác chết nằm úp sấp trong nhà của họ. 7:78; 7:91
- = Vậy, Người (Moussa) ném cây gậy của mình xuống, và kìa, nó biến thành một con rắn hiển nhiên. 7:107; 26:32
- = Và Người rút bàn tay của mình ra, và kìa, nó trở nên trắng sáng (rực rỡ) cho những người nhìn ngắm. 7:108; 26:33
- = Họ nói: "Chúng tôi đã tin tưởng vào Thượng Đế của các thế giới." 7:121; 26:47
- = Thượng Đế của Moussa và Haroun. 7:122; 26:48
- = Và Ta sẽ cho họ thời gian. Quả thật, Kế hoạch của Ta rất vững chắc. 7:183; 68:45
- = Ngài là Đấng đã cử Sứ Giả của Ngài đến với sự chỉ dẫn và Tôn giáo chân lý, để làm cho nó vượt trội hơn tất cả các tôn giáo, mặc dù những kẻ đa thần không thích điều đó. 9:33; 61:9
- = Hỡi Người Tiên Tri! Hãy chiến đấu chống lại những kẻ vô đức tin và những kẻ giả hình, và hãy nghiêm khắc với họ. Chỗ trú ngụ của họ là Hỏa Ngục, và thật là một nơi đến tồi tệ! 9:73; 66:9
- = Và họ nói: "Khi nào lời hứa này (sẽ xảy ra), nếu các người là những người trung thực?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = Và quả thật, Ta đã cử Moussa đến với các dấu hiệu của Ta và với một thẩm quyền rõ ràng. 11:96; 40:23
- = Và quả thật, Ta đã ban cho Moussa Kinh Sách, nhưng người ta đã tranh cãi về nó. Và nếu không vì một Lời phán đã được định trước từ Thượng Đế của Ngươi, thì nó đã được phân xử giữa họ. Và quả thật, họ đang ở trong sự nghi ngờ mơ hồ về nó. 11:110; 41:45
- = Điều đó không khó đối với Allah. 14:20; 35:17
- = "Và khi Ta đã nắn nên Người (Adam) và thổi vào Người một phần Linh Hồn của Ta, các ngươi hãy quỳ phủ phục trước Người." 15:29; 38:72
- = Vậy tất cả các Thiên Thần đều quỳ phủ phục. 15:30; 38:73
- = (Allah) phán: "Vậy hãy đi ra khỏi nó, vì quả thật, ngươi là kẻ bị trục xuất." 15:34; 38:77
- = (Iblis) thưa: "Lạy Thượng Đế của con! Vậy xin Ngài trì hoãn cho con đến Ngày mà họ sẽ được phục sinh." 15:36; 38:79
- = (Allah) phán: "Vậy quả thật, ngươi thuộc về những kẻ được trì hoãn." 15:37; 38:80
- = Cho đến Ngày của thời điểm đã được ấn định." 15:38; 38:81
- = Ngoại trừ những bề tôi chân thành của Ngài trong số họ. 15:40; 38:83
- = Quả thật, những người kính sợ sẽ ở trong những khu vườn và dòng suối. 15:45; 51:15
- = Người (Ibrahim) nói: "Vậy, công việc của các người là gì, hỡi các Sứ Giả?" 15:57; 51:31
- = Họ nói: "Quả thật, chúng tôi được cử đến với một dân tộc tội lỗi." 15:58; 51:32
- = Những ai tin tưởng và không trộn lẫn đức tin của họ với sự bất công – họ sẽ được an toàn, và họ là những người được hướng dẫn đúng đắn. 16:42; 29:59
- = Để họ từ chối những gì Ta đã ban cho họ. Vậy các ngươi hãy hưởng thụ, nhưng rồi các ngươi sẽ sớm biết. 16:55; 30:34
- = Rồi Người (Zul Qarnain) đi theo một con đường. 18:89; 18:92
