- Và đến 'Ad (TA đã cử) người anh em của họ là Hud. Y nói: Hỡi người dân của ta, hãy thờ phượng Allah; các người không có thần linh nào khác ngoài Ngài. (وَإِلَى عَادٍ أَخَاهُمْ هُودًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّnْ إِلَهٍ غَيْرُهُ) 7:65; 11:50
- Và những ai tin tưởng và làm việc thiện, TA sẽ đưa họ vào những Ngôi Vườn bên dưới có các dòng sông chảy, họ sẽ ở đó vĩnh viễn. (وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ سَنُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا) 4:57; 4:122
- Bên dưới có các dòng sông chảy, họ sẽ ở đó vĩnh viễn. Allah hài lòng về họ và họ hài lòng về Ngài. Đó là... (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا رَّضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ ذَلِكَ) 5:119; 98:8
- Hãy nói: Ta chỉ là một người phàm như các người; Ta được mặc khải rằng Thần linh của các người chỉ là một Thần linh Duy nhất. (قُلْ إِنَّمَا أَنَا بَشَرٌ مِّثْلُكُمْ يُوحَى إِلَيَّ أَنَّمَا إِلَهُكُمْ إِلَهٌ وَاحِدٌ) 18:110; 41:6
- Và trong nhân loại, có những kẻ tranh luận về Allah mà không có kiến thức, không có sự hướng dẫn và không có Kinh sách soi sáng. (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ وَلَا هُدًى وَلَا كِتَابٍ مُّنِيرٍ) 22:8; 31:20
- Ngài cho ban đêm lẫn vào ban ngày và ban ngày lẫn vào ban đêm; Ngài chế ngự mặt trời và mặt trăng; mỗi cái chạy theo quỹ đạo của nó cho đến một thời hạn ấn định... (يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي) 31:29; 35:13
- Từ trên trời, Ngài ban nước xuống và nhờ đó Ngài làm sống lại mặt đất sau khi nó chết. Quả thật, trong đó là một dấu hiệu cho người (biết lắng nghe). (مِنَ السَّمَاءِ مَاءً فَأَحْيَا بِهِ الْأَرْضَ بَعْدَ مَوْتِهَا إِنَّ فِي ذَلِكَ لَآيَةً لِّقَوْمٍ) 16:65; 30:24
- Quả thật, những kẻ vô đức tin, tài sản và con cái của chúng sẽ chẳng giúp ích được gì cho chúng trước Allah. Và chúng... (إِنَّ الَّذِينَ كَفَرُوا لَن تُغْنِيَ عَنْهُمْ أَمْوَالُهُمْ وَلَا أَوْلَادُهُم مِّنَ اللَّهِ شَيْئًا وَأُولَئِكَ) 3:10; 3:116
- Đấng đã tạo hóa các tầng trời, trái đất và mọi thứ ở giữa chúng trong sáu ngày, rồi Ngài ngự lên Ngai Vương (al-'Arsh). (الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ) 25:59; 32:4

