- Những thứ đó chỉ là những cái tên mà các ngươi và tổ tiên các ngươi đã đặt; Allah không ban xuống bất kỳ thẩm quyền nào cho chúng. Quả thật... (إِلَّا أَسْمَاءً سَمَّيْتُمُوهَا أَنتُمْ وَآبَاؤُكُم مَّا أَنزَلَ اللَّهُ بِهَا مِن سُلْطَانٍ إِنِ) 12:40; 53:23
