- Y nói: Các ngươi đã tin vào hắn trước khi ta cho phép các ngươi sao? Quả thật, hắn là kẻ cầm đầu các ngươi, kẻ đã dạy các người phép thuật. (قَالَ آمَنتُمْ لَهُ قَبْلَ أَنْ آذَنَ لَكُمْ إِنَّهُ لَكَبِيرُكُمُ الَّذِي عَلَّمَكُمُ السِّحْرَ) 20:71; 26:49
- Và không một linh hồn nào phải gánh chịu tội lỗi của người khác. Rồi các người sẽ trở về với Thượng Đế của các người, và Ngài sẽ cho các người biết những điều mà các người đã từng tranh cãi. (وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى ثُمَّ إِلَى رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 6:164; 39:7
- Và TA đã phán: Tất cả các ngươi hãy xuống, một số là kẻ thù của số khác. Và trên mặt đất, các ngươi sẽ có nơi cư trú và sự hưởng thụ đến một thời hạn nhất định. (وَقُلْنَا اهْبِطُوا بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِي الْأَرْضِ مُسْتَقَرٌّ وَمَتَاعٌ إِلَى حِينٍ) 2:36; 7:24
- Hai: Hãy nói: Ngài đã cấm hai con đực hay hai con cái, hay những gì nằm trong bụng của hai con cái? (اثْنَيْنِ قُلْ آلذَّكَرَيْنِ حَرَّمَ أَمِ الْأُنثَيَيْنِ أَمَّا اشْتَمَلَتْ عَلَيْهِ أَرْحَامُ الْأُنثَيَيْنِ) 6:143; 6:144

