- Đấng đã tạo hóa các tầng trời và trái đất trong sáu ngày, rồi Ngài ngự lên Ngai Vương (al-'Arsh). (الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ) 7:54; 10:3; 57:4
