- Quả thật, những kẻ nói rằng: Allah chính là Al-Masih, con trai của Maryam, đã vô đức tin. Hãy nói... (لَّقَدْ كَفَرَ الَّذِينَ قَالُوا إِنَّ اللَّهَ هُوَ الْمَسِيحُ ابْنُ مَرْيَمَ قُلْ) 5:17; 5:72
- Ngươi không thể làm cho người mù nghe được (lẽ thật) từ sự lầm lạc của họ. Ngươi chỉ có thể làm cho người có đức tin nơi các dấu hiệu của TA nghe được, vì họ là những người Muslim (thần phục). (الْعُمْيِ عَن ضَلَالَتِهِمْ إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بِآيَاتِنَا فَهُم مُّسْلِمُونَ) 27:81; 30:53
- Hình ảnh của cuộc sống trần tục giống như nước mà TA ban xuống từ trên trời, và cây cỏ của trái đất trộn lẫn với nó... (مَثَلُ الْحَيَاةِ الدُّنْيَا كَمَاءٍ أَنزَلْنَاهُ مِنَ السَّمَاءِ فَاخْتَلَطَ بِهِ نَبَاتُ الْأَرْضِ) 10:24; 18:45
- Hãy đưa vào đó (con tàu) từ mỗi loài một cặp, và gia đình của ngươi, ngoại trừ những kẻ đã có phán quyết trước đối với họ... (فِيهَا مِن كُلٍّ زَوْجَيْنِ اثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ الْقَوْلُ) 11:40; 23:27
- Ta không nói với các người rằng Ta có những kho báu của Allah, và Ta không biết điều vô hình, và Ta không nói... (لَّا أَقُولُ لَكُمْ عِندِي خَزَائِنُ اللَّهِ وَلَا أَعْلَمُ الْغَيْبَ وَلَا أَقُولُ) 6:50; 11:31
- Quả thật, Allah là Đấng rất mực nhân từ đối với nhân loại, nhưng hầu hết nhân loại không biết tri ân. (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَشْكُرُونَ) 2:243; 40:61
- Và bất kỳ dấu hiệu nào trong các dấu hiệu của Thượng Đế của chúng đến với chúng, chúng chỉ quay đi khỏi nó. (وَمَا تَأْتِيهِم مِّنْ آيَةٍ مِّنْ آيَاتِ رَبِّهِمْ إِلَّا كَانُوا عَنْهَا مُعْرِضِينَ) 6:4; 36:46
- Và hãy sợ Ngày mà không một linh hồn nào có thể giúp gì cho linh hồn khác, và không có sự can thiệp nào được chấp nhận từ nó. (وَاتَّقُوا يَوْمًا لَّا تَجْزِي نَفْسٌ عَن نَّفْسٍ شَيْئًا وَلَا يُقْبَلُ مِنْهَا) 2:48; 2:123
- Quả thật, ngươi không thể làm cho người chết nghe được, và không thể làm cho người điếc nghe được lời kêu gọi khi họ quay lưng bỏ đi. (إِنَّكَ لَا تُسْمِعُ الْمَوْتَى وَلَا تُسْمِعُ الصُّمَّ الدُّعَاءَ إِذَا وَلَّوْا مُدْبِرِينَ) 27:80; 30:52
- Các người bị cấm (ăn) xác chết, máu, thịt heo, và những gì được giết mổ nhân danh kẻ khác ngoài Allah. (حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ) 5:3; 16:115
- Mọi vật trong các tầng trời và trái đất đều tán dương Allah, và Ngài là Đấng Toàn Năng, Đấng Chí Minh. (سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَهُوَ الْعَزِيزُ الْحَكِيمُ) 59:1; 61:1
- Ngoại trừ những ai sám hối và sửa đổi (bản thân) sau đó. Quả thật, Allah là Đấng Tha Thứ, Đấng Nhân Từ. (إِلَّا الَّذِينَ تَابُوا مِن بَعْدِ ذَلِكَ وَأَصْلَحُوا فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ) 3:89; 24:5
- (Điều đã được) các vị Nabi nhận được từ Thượng Đế của họ; chúng tôi không phân biệt giữa bất kỳ ai trong số họ, và chúng tôi là những người thần phục Ngài (Muslim). (النَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُ مُسْلِمُونَ) 2:136; 3:84
- (Được cử đến) từ Thượng Đế của ngươi, để ngươi cảnh báo một dân tộc mà chưa có người cảnh báo nào đến với họ trước ngươi, hy vọng họ... (مِّن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّا أَتَاهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ) 28:46; 32:3
- Hỡi Nabi! Hãy chiến đấu chống lại những kẻ vô đức tin và những kẻ giả tạo, và hãy cứng rắn với chúng. Nơi ở của chúng là Hỏa Ngục (Jahannam) – một đích đến thật tồi tệ! (يَا أَيُّهَا النَّبِيُّ جَاهِدِ الْكُفَّارَ وَالْمُنَافِقِينَ وَاغْلُظْ عَلَيْهِمْ وَمَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ) 9:73; 66:9
- Quả thật, Thượng Đế của ngươi sẽ phán xét giữa họ vào Ngày Phục Sinh về những điều họ đã từng tranh cãi. (إِنَّ رَبَّكَ يَقْضِي بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 10:93; 45:17
- Y nói: Lạy Thượng Đế của bề tôi, xin Ngài ban cho bề tôi một dấu hiệu. Ngài phán: Dấu hiệu của ngươi là ngươi sẽ không nói chuyện với mọi người. (قَالَ رَبِّ اجْعَل لِّي آيَةً قَالَ آيَتُكَ أَلَّا تُكَلِّمَ النَّاسَ) 3:41; 19:10
- Vì vậy, hãy quay mặt ngươi về hướng Masjid Al-Haram. Và bất cứ nơi nào các người ở, hãy quay mặt về hướng đó. (فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ) 2:144; 2:150
- Hỡi con cháu của Israel! Hãy nhớ lại ân huệ của Ta mà Ta đã ban cho các người, và việc Ta đã ưu ái các người hơn các thế giới. (يَا بَنِي إِسْرَائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَالَمِينَ) 2:47; 2:122
- Bảy con bò cái béo tốt bị bảy con bò cái ốm yếu ăn thịt; và bảy bông lúa xanh tốt và những bông khác khô héo... (سَبْعَ بَقَرَاتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعَ سُنبُلَاتٍ خُضْرٍ وَأُخَرَ يَابِسَاتٍ) 12:43; 12:46
- Và mỗi cộng đồng có một thời hạn nhất định; khi thời hạn của họ đến, họ không thể trì hoãn hay thúc đẩy nó dù chỉ một giây. (وَلِكُلِّ أُمَّةٍ أَجَلٌ فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49
- (Những gì đã) bị giết mổ nhân danh kẻ khác ngoài Allah, nhưng ai bị bắt buộc (vì đói), không cố tình và không vượt quá giới hạn, thì... (أُهِلَّ لِغَيْرِ اللَّهِ بِهِ فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ) 6:145; 16:115
- Và khi chúng được bảo: Hãy theo điều mà Allah đã ban xuống, chúng nói: Không, chúng tôi sẽ theo những gì chúng tôi thấy cha ông mình đã làm. (وَإِذَا قِيلَ لَهُمُ اتَّبِعُوا مَا أَنزَلَ اللَّهُ قَالُوا بَلْ نَتَّبِعُ مَا) 2:170; 31:21
- Y nói: Hỡi người dân của ta, hãy thờ phượng Allah; các người không có thần linh nào khác ngoài Ngài. Vậy các người không sợ (Ngài) sao? (قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23
Matching Phrases 10 words
- Họ đi lại trên mặt đất và nhìn xem kết cuộc của những người trước họ đã ra sao. (يَسِيرُوا فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِن قَبْلِهِمْ) 12:109; 30:9; 30:42; 35:44; 40:82; 47:10
- Và ai bất công hơn kẻ bịa đặt điều nói dối cho Allah hoặc phủ nhận (sự thật)? (وَمَنْ أَظْلَمُ مِمَّنِ افْتَرَى عَلَى اللَّهِ كَذِبًا أَوْ كَذَّبَ) 6:21; 7:37; 10:17; 29:68
- Quả thật, Thượng Đế của Ngươi biết rõ nhất ai lạc khỏi con đường của Ngài, và Ngài biết rõ nhất. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ مَن يَضِلُّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 6:117; 16:125; 53:30; 68:7
- Há họ không đi lại trên mặt đất để nhìn xem kết cuộc của những người trước họ đã ra sao? (أَوَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِن) 30:9; 35:44; 40:82; 47:10
